52	func Pending(headers map[string]Header, messages []Message) []string {
53		var ids []string
54		for _, message := range messages {
55			header, ok := headers[message.From]
56			if !ok || !header.Trusted || header.Height < message.ProofAt {
57				ids = append(ids, message.ID)
58			}
59		}
60		sort.Strings(ids)
61		return ids
