779		raw := runNormalizeRaw(t, input)
780		for _, want := range []string{"9007199254740993", "1.0000000000000000001", "1e400", "1e-400"} {
781			if !strings.Contains(raw, want) {
782				t.Fatalf("serialized output must contain the exact literal %s, got %s", want, raw)
783			}
784		}
785		if strings.Contains(raw, "9007199254740992") {
786			t.Fatalf("big integer was rounded to a float64 neighbor: %s", raw)
787		}
788		if strings.Contains(raw, "Infinity") || strings.Contains(raw, "inf") {
789			t.Fatalf("out-of-float-range exponent must not serialize as infinity: %s", raw)
790		}
791	}
792	
793	func TestNormalizeExtraNestedPrecision(t *testing.T) {
794		// Precision preservation applies at every depth of unmapped objects and
795		// arrays, not just the top level; array order and the JSON types of
796		// values adjacent to the numbers must survive too.
797		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"a","payload":{` +
798			`"deep":{"id":9007199254740993},` +
799			`"list":[1.0000000000000000001,9007199254740993,"9007199254740993",true,null,3]}}`
800		results := runNormalizeJSON(t, input)
801		if results[0]["ok"] != true {
802			t.Fatalf("nested high-precision numbers must succeed, got %#v", results[0])
803		}
804		payload, ok := extraOf(t, results[0])["payload"].(map[string]any)
805		if !ok {
806			t.Fatalf("payload object must be preserved, got %#v", extraOf(t, results[0])["payload"])
807		}
808		deep, ok := payload["deep"].(map[string]any)
809		if !ok {
810			t.Fatalf("nested object level must be preserved, got %#v", payload["deep"])
811		}
812		mustNumber(t, deep["id"], "9007199254740993")
813	
814		list, ok := payload["list"].([]any)
815		if !ok || len(list) != 6 {
816			t.Fatalf("array level and length must be preserved, got %#v", payload["list"])
817		}
818		mustNumber(t, list[0], "1.0000000000000000001")
819		mustNumber(t, list[1], "9007199254740993")
820		// A string that spells a number stays a string; it is not converted.
821		if s, ok := list[2].(string); !ok || s != "9007199254740993" {
822			t.Fatalf("string-formed number must stay a string, got %T (%v)", list[2], list[2])
823		}
824		if list[3] != true {
825			t.Fatalf("adjacent boolean must keep its type, got %#v", list[3])
826		}
827		if list[4] != nil {
828			t.Fatalf("adjacent null must keep its type, got %#v", list[4])
829		}
830		mustNumber(t, list[5], "3")
831	}
832	
833	func TestNormalizeInputExtraKeepsPrecisionAndNesting(t *testing.T) {
834		// An input's own "extra" field is an ordinary unmapped field: it lands
835		// inside the output extra as one nested object, its high-precision
836		// numbers survive, and it is not flattened into the sibling fields.
837		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"a",` +
838			`"extra":{"balance":9007199254740993,"ratio":1.0000000000000000001,"tags":["x",1e400]},` +
839			`"other":2}`
840		results := runNormalizeJSON(t, input)
841		if results[0]["ok"] != true {
842			t.Fatalf("nested input extra must succeed, got %#v", results[0])
843		}
844		extra := extraOf(t, results[0])
845		if len(extra) != 2 {
846			t.Fatalf("input extra must stay one nested field, not be flattened: %#v", extra)
847		}
848		inner, ok := extra["extra"].(map[string]any)
849		if !ok {
850			t.Fatalf("input extra must be a nested object under extra, got %#v", extra["extra"])
851		}
852		mustNumber(t, inner["balance"], "9007199254740993")
853		mustNumber(t, inner["ratio"], "1.0000000000000000001")
854		tags, ok := inner["tags"].([]any)
855		if !ok || len(tags) != 2 || tags[0] != "x" {
856			t.Fatalf("nested array inside input extra not preserved: %#v", inner["tags"])
857		}
858		mustNumber(t, tags[1], "1e400")
859		if _, leaked := extra["balance"]; leaked {
860			t.Fatalf("nested extra fields must not be hoisted to the top level: %#v", extra)
861		}
862		mustNumber(t, extra["other"], "2")
863	}
864	
865	func TestNormalizeMappedFieldsStillRejectNumbers(t *testing.T) {
866		// Precision preservation is scoped to unmapped data: a number — even a
867		// legal high-precision one — in a mapped field still fails type checks.
868		cases := []struct {
869			input string
870			field string
871		}{
872			{`{"timestamp":9007199254740993,"action":"a"}`, FieldTimestamp},
873			{`{"time":1.0000000000000000001,"action":"a"}`, FieldTimestamp},
874			{`{"timestamp":"2026-01-02T00:00:00Z","action":123}`, FieldAction},
875			{`{"timestamp":"2026-01-02T00:00:00Z","event_type":1e400}`, FieldAction},
876			{`{"timestamp":"2026-01-02T00:00:00Z","action":"a","source_ip":9007199254740993}`, FieldSourceIP},
877			{`{"timestamp":"2026-01-02T00:00:00Z","action":"a","src_ip":1e400}`, FieldSourceIP},
878		}
879		for _, tc := range cases {
880			results := runNormalize(t, tc.input)
881			if results[0]["ok"] != false {
882				t.Fatalf("number in mapped field must fail: %s", tc.input)
883			}
884			if _, exists := results[0]["event"]; exists {
885				t.Fatalf("failure must not emit a partial event: %s", tc.input)
886			}
887			msg, _ := results[0]["error"].(string)
888			if !strings.Contains(msg, tc.field) {
889				t.Fatalf("error for %s must name field %q, got %q", tc.input, tc.field, msg)
890			}
891		}
892	}
893	
894	func TestNormalizeInvalidJSONNumbersFail(t *testing.T) {
895		// Tokens that are not legal JSON numbers must fail the whole line with
896		// an error and no partial event, even inside unmapped fields.
897		cases := []string{
898			`{"timestamp":"2026-01-02T00:00:00Z","action":"a","x":NaN}`,
899			`{"timestamp":"2026-01-02T00:00:00Z","action":"a","x":Infinity}`,
900			`{"timestamp":"2026-01-02T00:00:00Z","action":"a","x":-Infinity}`,
901			`{"timestamp":"2026-01-02T00:00:00Z","action":"a","x":01}`,
902			`{"timestamp":"2026-01-02T00:00:00Z","action":"a","x":+1}`,
903			`{"timestamp":"2026-01-02T00:00:00Z","action":"a","x":1.}`,
904			`{"timestamp":"2026-01-02T00:00:00Z","action":"a","x":{"nested":007}}`,
905		}
906		for _, in := range cases {
907			results := runNormalize(t, in)
908			if len(results) != 1 || results[0]["ok"] != false {
909				t.Fatalf("invalid JSON number must fail: %s -> %#v", in, results)
910			}
911			if _, exists := results[0]["event"]; exists {
912				t.Fatalf("invalid JSON number must not emit a partial event: %s", in)
913			}
914			if msg, _ := results[0]["error"].(string); msg == "" {
915				t.Fatalf("invalid JSON number must produce an error message: %s", in)
916			}
917		}
918	}
919	
920	func TestNormalizeMixedStreamHighPrecision(t *testing.T) {
921		// In one stream, invalid-number lines and wrong-typed mapped fields
922		// fail while surrounding legal high-precision logs still succeed in
923		// order; the failure count covers only the genuinely bad lines.
924		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"a","big":9007199254740993}` + "\n" +
925			`{"timestamp":"2026-01-02T00:00:00Z","action":"a","x":NaN}` + "\n" +
926			`{"timestamp":9007199254740993,"action":"a"}` + "\n" +
927			`{"timestamp":"2026-01-02T00:00:00Z","action":"b","extra":{"v":1.0000000000000000001}}` + "\n"
928		var out bytes.Buffer
929		failures, err := NormalizeReader(strings.NewReader(input), &out)
930		if err != nil {
931			t.Fatalf("NormalizeReader returned error: %v", err)
932		}
933		if failures != 2 {
934			t.Fatalf("expected exactly 2 failures (legal extra numbers must not count), got %d", failures)
935		}
936		results := []map[string]any{}
937		dec := json.NewDecoder(bytes.NewReader(out.Bytes()))
938		dec.UseNumber()
939		for {
940			var m map[string]any
941			if err := dec.Decode(&m); err != nil {
942				if err == io.EOF {
943					break
944				}
945				t.Fatalf("decoding result: %v", err)
946			}
947			results = append(results, m)
948		}
949		if len(results) != 4 {
950			t.Fatalf("expected 4 results, got %d: %#v", len(results), results)
951		}
952		if results[0]["ok"] != true || results[1]["ok"] != false || results[2]["ok"] != false || results[3]["ok"] != true {
953			t.Fatalf("ok pattern mismatch: %#v", results)
954		}
955		mustNumber(t, extraOf(t, results[0])["big"], "9007199254740993")
956		inner, ok := extraOf(t, results[3])["extra"].(map[string]any)
957		if !ok {
958			t.Fatalf("line 4 input extra must stay nested, got %#v", extraOf(t, results[3]))
959		}
960		mustNumber(t, inner["v"], "1.0000000000000000001")
961	}
962	
963	func TestNormalizeCRLF(t *testing.T) {
964		input := "{\"timestamp\":\"2026-01-02T00:00:00Z\",\"action\":\"a\"}\r\n\r\nnot json\r\n"
965		results := runNormalize(t, input)
966		if len(results) != 2 || results[0]["line"] != float64(1) || results[1]["line"] != float64(3) {
