182			// The inner text spells two "action" members, but it lives inside a
183			// JSON string value; escaping an "i" inside that value changes only
184			// the decoded string text.
185			input := `{"timestamp":"2026-01-02T00:00:00Z","action":"a",` +
186				`"note":"{\"action\":1, \"action\":2}","invalue":"act` + "\\u0069" + `on twice"}`
