10	// Regression coverage for chunked input delivery: the bytes a source hands
11	// over per Read are not aligned to log lines, so the same complete input may
12	// arrive as single bytes, as alternating short and long pieces, or as one
13	// piece spanning several records. Chunking must never change the normalized
14	// events, their order, the physical line numbers, or the failure count, and
15	// a partial chunk must never be mistaken for a whole log line. All inputs
16	// are built in-process, so every case reproduces deterministically offline.
17	
18	// chunkReader replays data in pieces whose sizes cycle through the given
19	// pattern, mirroring a source that delivers arbitrary byte counts per Read.
20	// It never returns (0, nil): once data is exhausted every Read is io.EOF.
21	type chunkReader struct {
22		data  []byte
23		sizes []int
24		pos   int
25		step  int
26	}
27	
28	func (c *chunkReader) Read(p []byte) (int, error) {
29		if c.pos >= len(c.data) {
30			return 0, io.EOF
31		}
32		n := c.sizes[c.step%len(c.sizes)]
33		c.step++
34		if n <= 0 {
35			// A zero-length piece delivers nothing; skip it rather than
36			// returning (0, nil), which a Reader must not do while data remains.
37			return c.Read(p)
38		}
39		if n > len(p) {
40			n = len(p)
41		}
42		if rem := len(c.data) - c.pos; n > rem {
43			n = rem
44		}
45		copy(p, c.data[c.pos:c.pos+n])
46		c.pos += n
47		return n, nil
48	}
