50	// chunkPatterns are the delivery shapes every fixture must survive: byte at
51	// a time (every possible split point, including inside UTF-8 sequences,
52	// escape sequences, and CRLF pairs), irregular alternation of short and long
53	// pieces, and pieces large enough to carry several whole records at once.
54	var chunkPatterns = []struct {
55		name  string
56		sizes []int
57	}{
58		{"single byte at a time", []int{1}},
59		{"alternating short and long pieces", []int{1, 4096, 2, 7, 1024, 3, 64}},
60		{"odd small sizes", []int{2, 3, 5, 7, 11, 13}},
61		{"one piece spans many records", []int{1 << 20}},
62	}
