1	package relayproof
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"strings"
10		"testing"
11	)
12	
13	// Regression coverage for stream-level interruptions: the error a caller
14	// receives must stay distinguishable from a single invalid log line, the
15	// failure count must cover only lines that failed normalization, and read
16	// failures must not be masked by later write failures. All fault injection
17	// is in-process and scripted, so the behavior reproduces deterministically
18	// without real pipes, networks, or device failures.
19	
20	var (
21		errSimulatedRead  = errors.New("simulated input device read failure")
22		errSimulatedWrite = errors.New("simulated output device write failure")
23	)
24	
25	// scriptReader replays fixed (data, err) Read results in order. A step may
26	// return data together with an error, mirroring a reader that loses its
27	// underlying device after delivering a truncated final fragment. After the
28	// script is exhausted every further Read returns io.EOF.
29	type scriptReader struct {
30		steps []scriptStep
31		i     int
32	}
33	
34	type scriptStep struct {
35		data []byte
36		err  error
37	}
38	
39	func (s *scriptReader) Read(p []byte) (int, error) {
40		if s.i >= len(s.steps) {
41			return 0, io.EOF
42		}
43		step := s.steps[s.i]
44		s.i++
45		n := copy(p, step.data)
46		if n < len(step.data) {
47			panic("scriptReader step larger than the caller's buffer; shrink the script data")
48		}
49		return n, step.err
50	}
51	
52	// failWriter accepts exactly allowBytes bytes in total, then fails. From the
53	// failing Write up to partial bytes are still recorded, so tests can model
54	// output cut off mid-record. Everything accepted is kept for inspection.
55	type failWriter struct {
56		buf        bytes.Buffer
57		allowBytes int
58		partial    int
59		err        error
60		failed     bool
61	}
62	
63	func (w *failWriter) Write(p []byte) (int, error) {
64		accepted := 0
65		if w.allowBytes > 0 {
66			n := len(p)
67			if n > w.allowBytes {
68				n = w.allowBytes
69			}
70			w.buf.Write(p[:n])
71			w.allowBytes -= n
72			accepted, p = n, p[n:]
73			if len(p) == 0 {
74				return accepted, nil
75			}
76		}
77		m := w.partial
78		if m > len(p) {
79			m = len(p)
80		}
81		w.buf.Write(p[:m])
82		w.failed = true
83		return accepted + m, w.err
84	}
85	
86	// decodeResults parses complete JSON-object-per-line output. A non-EOF
87	// decode error fails the test: healthy output must always be whole records.
88	func decodeResults(t *testing.T, data []byte) []map[string]any {
89		t.Helper()
90		var results []map[string]any
91		dec := json.NewDecoder(bytes.NewReader(data))
92		for {
93			var m map[string]any
94			if err := dec.Decode(&m); err != nil {
95				if errors.Is(err, io.EOF) {
96					return results
97				}
98				t.Fatalf("output must consist of whole result records, got decode error %v after %d records: %q", err, len(results), string(data))
99			}
100			results = append(results, m)
101		}
102	}
103	
104	// decodePrefix parses as many whole records as a possibly-truncated output
105	// contains; a write interruption is allowed to leave a non-record tail, so
106	// a trailing syntax error is expected rather than fatal.
107	func decodePrefix(t *testing.T, data []byte) []map[string]any {
108		t.Helper()
109		var results []map[string]any
110		dec := json.NewDecoder(bytes.NewReader(data))
111		for {
112			var m map[string]any
113			if err := dec.Decode(&m); err != nil {
114				if errors.Is(err, io.EOF) {
115					t.Fatalf("expected truncated trailing output, got a clean record boundary")
116				}
117				return results
118			}
119			results = append(results, m)
120		}
121	}
122	
123	func validLog(action string) string {
124		return `{"timestamp":"2026-01-02T00:00:00Z","action":"` + action + `"}`
125	}
126	
127	func bigValidLog(action string) string {
128		return fmt.Sprintf(`{"timestamp":"2026-01-02T00:00:00Z","action":%q,"pad":%q}`,
129			action, strings.Repeat("p", 5000))
130	}
131	
132	// encodedRecord is the exact byte form NormalizeReader writes for one line
133	// (json.Encoder appends a newline), used to script writer byte budgets.
134	func encodedRecord(t *testing.T, lineNo int, raw string) []byte {
135		t.Helper()
136		b, err := json.Marshal(NormalizeLine(lineNo, []byte(raw)))
137		if err != nil {
138			t.Fatal(err)
139		}
140		return append(b, '\n')
141	}
142	
143	// A field-invalid line embedded in a healthy stream produces a failure
144	// result carrying its original line number, later valid lines keep coming,
145	// and the returned error is nil: per-line failures are not I/O failures.
146	func TestNormalizeIOInvalidLineIsNotStreamError(t *testing.T) {
147		input := validLog("a") + "\n" +
148			`{"timestamp":"not-a-time","action":"b"}` + "\n" +
149			validLog("c") + "\n"
150		var out bytes.Buffer
151		failures, err := NormalizeReader(strings.NewReader(input), &out)
152		if err != nil {
153			t.Fatalf("healthy stream must return nil error, got %v", err)
154		}
155		if errors.Is(err, ErrLogRead) || errors.Is(err, ErrLogWrite) {
156			t.Fatalf("nil error cannot match an I/O sentinel: %v", err)
157		}
158		if failures != 1 {
159			t.Fatalf("only the invalid log must count as a failure, got %d", failures)
160		}
161		results := decodeResults(t, out.Bytes())
162		if len(results) != 3 {
163			t.Fatalf("expected 3 results, got %#v", results)
164		}
165		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
166			t.Fatalf("line 1 mismatch: %#v", results[0])
167		}
168		if results[1]["line"] != float64(2) || results[1]["ok"] != false {
169			t.Fatalf("invalid line must keep line number 2: %#v", results[1])
170		}
171		if msg, _ := results[1]["error"].(string); !strings.Contains(msg, FieldTimestamp) {
172			t.Fatalf("per-line error explanation must survive in output, got %q", msg)
173		}
174		if _, exists := results[1]["event"]; exists {
175			t.Fatalf("failed line must not carry an event: %#v", results[1])
176		}
177		if results[2]["line"] != float64(3) || results[2]["ok"] != true {
178			t.Fatalf("valid line 3 must still be emitted: %#v", results[2])
179		}
180		if eventOf(t, results[2])["action"] != "c" {
181			t.Fatalf("line 3 must preserve order and content")
182		}
183	}
184	
185	// When the input stream fails after whole lines, everything already read is
186	// processed in order and flushed; the read error is reported wrapped with
187	// ErrLogRead, the failure count covers only genuinely invalid complete
188	// lines, and an unterminated fragment delivered with the failure is neither
189	// normalized, counted, nor emitted.
190	func TestNormalizeIOReadErrorAfterCompleteLines(t *testing.T) {
191		complete := validLog("a") + "\n" +
192			`{"timestamp":"not-a-time","action":"b"}` + "\n" +
193			validLog("c") + "\n"
194		cases := []struct {
195			name     string
196			fragment []byte
197		}{
198			{"error carries an unterminated fragment", []byte(`{"timestamp":"FRAGMENT-MARKER","action":`)},
199			{"error stands alone after a newline", nil},
200			{"error carries only blank bytes", []byte("   ")},
201		}
202		for _, tc := range cases {
