294					t.Fatalf("want ErrLogWrite wrapping the cause, got %v", err)
295				}
296				if errors.Is(err, ErrLogRead) {
297					t.Fatalf("a healthy reader must not tag the error as a read failure: %v", err)
298				}
299				if !w.failed {
